<section class="container section narrow"><div class="auth-card"><div class="auth-brand-lockup"><img src="/assets/images/fixhome_logo.webp" alt="FixHome"><span>Home services & marketplace</span></div><h1>Đăng ký khách hàng</h1><form method="post" action="/register"><?= csrf_field() ?><label for="register-name">Họ và tên</label><input id="register-name" name="name" required autocomplete="name"><label for="register-phone">Số điện thoại</label><input id="register-phone" type="tel" inputmode="tel" name="phone" required autocomplete="tel" placeholder="0901234567 hoặc +84901234567"><label for="register-email">Email</label><input id="register-email" type="email" name="email" required autocomplete="email"><label for="register-password">Mật khẩu</label><p class="field-help"><?= e(PasswordPolicy::HELP_TEXT) ?></p><span class="password-field"><input id="register-password" type="password" name="password" minlength="12" maxlength="72" required autocomplete="new-password"><?= password_visibility_button() ?></span><label for="register-password-confirm">Nhập lại mật khẩu</label><span class="password-field"><input id="register-password-confirm" type="password" name="password2" minlength="12" maxlength="72" required autocomplete="new-password"><?= password_visibility_button() ?></span><button class="btn full-btn">Tạo tài khoản</button></form></div></section>
